const HEBREW_CUSTOM_KEY='rikiCustomShorashimV1';
function hebrewCustomRead(){try{const x=JSON.parse(localStorage.getItem(HEBREW_CUSTOM_KEY)||'[]');return Array.isArray(x)?x.filter(a=>Array.isArray(a)&&a.length===3&&a.every(v=>typeof v==='string')):[]}catch(_){return []}}
W.push(...hebrewCustomRead().filter(a=>!W.some(w=>w[0]===a[0])));
function hebrewRootEditor(){game='hebrew-editor';session=null;const safe=x=>esc(x);app.innerHTML=`<section class="panel"><button class="secondary" id="hebrewEditorBack">← Hebrew games</button><h2>✏️ Add Hebrew שורשים</h2><p>Add a shoresh, its English meaning and a memory hint. New roots join the Hebrew question pool in the existing games on this device.</p><form id="hebrewRootForm" style="display:grid;gap:12px"><label>שורש (Hebrew root)<input id="hebrewNewRoot" dir="rtl" maxlength="12" required placeholder="כתב"></label><label>English meaning<input id="hebrewNewMeaning" maxlength="100" required placeholder="Write"></label><label>Memory hint<input id="hebrewNewHint" maxlength="180" required placeholder="Think of writing a letter"></label><button class="primary" type="submit">Save new shoresh</button></form><p id="hebrewRootStatus" role="status"></p></section><section class="panel"><h3>My added roots</h3><div id="hebrewRootList"></div></section>`;
const draw=()=>{const list=hebrewCustomRead();$('#hebrewRootList').innerHTML=list.length?list.map((r,i)=>`<div style="padding:12px 0;border-bottom:1px solid #ddd"><strong dir="rtl">${safe(r[0])}</strong> — ${safe(r[1])}<p>${safe(r[2])}</p><button class="secondary" data-remove-root="${i}">Remove</button></div>`).join(''):'No added roots yet.';document.querySelectorAll('[data-remove-root]').forEach(b=>b.onclick=()=>{const roots=hebrewCustomRead(),removed=roots.splice(Number(b.dataset.removeRoot),1)[0];try{localStorage.setItem(HEBREW_CUSTOM_KEY,JSON.stringify(roots));const idx=W.findIndex(w=>w[0]===removed[0]);if(idx>=0)W.splice(idx,1);draw()}catch(_){$('#hebrewRootStatus').textContent='Could not save changes.'}})};
$('#hebrewEditorBack').onclick=menu;$('#hebrewRootForm').onsubmit=e=>{e.preventDefault();const root=$('#hebrewNewRoot').value.trim().replace(/[\u0591-\u05c7]/g,''),meaning=$('#hebrewNewMeaning').value.trim(),hint=$('#hebrewNewHint').value.trim();if(!/^[\u05d0-\u05ea]{2,5}$/.test(root)){ $('#hebrewRootStatus').textContent='Enter 2–5 Hebrew letters for the root.';return}if(W.some(w=>w[0]===root)){ $('#hebrewRootStatus').textContent='This root is already in the games.';return}const roots=hebrewCustomRead();roots.push([root,meaning,hint]);try{localStorage.setItem(HEBREW_CUSTOM_KEY,JSON.stringify(roots));W.push([root,meaning,hint]);$('#hebrewRootStatus').textContent='Saved! Your new root is ready for Hebrew games.';e.target.reset();draw()}catch(_){$('#hebrewRootStatus').textContent='Could not save on this device.'}};draw()}
const $=s=>document.querySelector(s), app=$('#app');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
