function updateStats(){const coinEl=$('#coins'),streakEl=$('#streak');if(coinEl)coinEl.textContent='🪙 '+coins;if(streakEl)streakEl.textContent='🔥 '+streak;const scoreEl=document.querySelector('.gamehead .pill');if(scoreEl&&session)scoreEl.textContent=(session.score||0)+' ⭐';document.querySelectorAll('[data-live-coins]').forEach(el=>el.textContent='🪙 '+coins);document.querySelectorAll('.quest-hint').forEach(el=>{const t=el.textContent;el.textContent=t.replace(/🪙\s*[\d,]+\s*coins\b/,'🪙 '+coins+' coins')});document.querySelectorAll('[data-live-stars]').forEach(el=>{if(session)el.textContent='⭐ '+(session.score||0)})}
