render=function(){if(extraGames[game])return renderExtra();return extraRender()};
function nextExtra(){session.at++;session.tries=0;session.locked=false;session.stage=0;session.parts=[];if(session.at>=session.order.length){frame('🏆 Mission completed',`<div class="extra-stage"><div class="scene">🏆 🎊 💎</div><h2>Fantastic work!</h2><p>You earned ${session.score} stars! Your coins are ready for the dollhouse.</p><button class="primary" id="againExtra">Play again</button> <button class="secondary" id="backExtra">Game menu</button></div>`);$('#againExtra').onclick=()=>start(game);$('#backExtra').onclick=menu;celebrate()}else renderExtra()}
function answerExtra(choice,button){const s=session,id=s.order[s.at];if(s.locked)return;if(choice!==id){s.tries++;recordLearning(id,false);button.disabled=true;button.classList.add('wrong');audio('bad');$('#extraFeedback').innerHTML=`<div class="feedback try">Try another one! ${s.tries>1?'Hint: '+esc(W[id][2]):''}</div>`;return}recordLearning(id,true,s.tries>0);s.locked=true;s.score+=s.tries?3:6;award(s.tries?5:11);audio('good');celebrate();if(game==='aquarium'){living.fish=living.fish||[];living.fish.push(['🐠','🐟','🐡','🪼'][s.at%4]);saveLiving()}if(game==='claw'){let prize=['🧸','🎀','📚','🦄','💎','🪴','🎂','🐚'][s.at%8];living.prizes=living.prizes||[];living.prizes.push(prize);saveLiving()}const result={cake:'🎂 Layer decorated! The customer is delighted!',boutique:'👗 Your customer loves the outfit!',claw:'🕹️ You grabbed a surprise prize!',aquarium:'🐠 A new fish joins your aquarium!',quest:'🌟 Mission accomplished!'}[game];$('#extraFeedback').innerHTML=`<div class="feedback good">${result} <strong>${esc(W[id][0])}</strong> = ${esc(W[id][1])}</div><button class="primary" id="extraNext">${s.at===s.order.length-1?'Finish mission':'Continue →'}</button>`;$('#extraNext').onclick=nextExtra}
function renderExtra(){const s=session,id=s.order[s.at],w=W[id],opts=optionsFor(id,3,true),n=s.at+1;let scene='',instruction='';if(game==='cake'){scene=`<div class="scene">👩‍🍳 ${'🎂'.repeat(Math.min(3,1+Math.floor(n/3)))} ${['🍓','🍒','🧁','🍬'][n%4]}</div><h3>Customer ${n}: Birthday cake order!</h3>`;instruction=`Choose the frosting label for <b>${esc(w[1])}</b> to decorate the next layer.`}else if(game==='boutique'){scene=`<div class="scene">🛍️ 👗 👠 🎀</div><h3>Welcome to the fashion boutique!</h3>`;instruction=`Your customer wants the outfit labeled <b>${esc(w[1])}</b>. Read the Hebrew tags!`}else if(game==='claw'){scene=`<div class="scene">🕹️ 🧸 🦄 🎁</div><h3>Catch a surprise!</h3>`;instruction=`Guide the claw to the prize with the shoresh for <b>${esc(w[1])}</b>.`}else if(game==='aquarium'){scene=`<div class="scene">🐠 🪸 🐚 🫧</div><h3>Rescue a new fish!</h3>`;instruction=`Open the sea gate labeled with the shoresh for <b>${esc(w[1])}</b>.`}else{scene=`<div class="scene">🏰 🌈 🗺️ 🌟</div><h3>Mission ${n}: Find the magic key!</h3>`;instruction=`Find the shoresh for <b>${esc(w[1])}</b> to unlock the next adventure.`}frame(extraGames[game][0]+' '+extraGames[game][1],`<div class="creative-progress"><span class="pill">Challenge ${n} / ${s.order.length}</span><span class="pill">⭐ ${s.score} stars</span></div><div class="extra-stage">${scene}<p>${instruction}</p></div><div class="extra-choices">${opts.map((j,k)=>`<button data-extra-choice="${j}" ${s.locked?'disabled':''}><span>${game==='cake'?['🍓','🍫','🍦'][k]:game==='boutique'?['👗','👟','👑'][k]:game==='claw'?['🧸','🦄','🎁'][k]:game==='aquarium'?['🐟','🐠','🐡'][k]:['🗝️','💎','⭐'][k]}</span><br>${esc(W[j][0])}</button>`).join('')}</div><div id="extraFeedback"></div>`,100*s.at/s.order.length);document.querySelectorAll('[data-extra-choice]').forEach(b=>b.onclick=()=>answerExtra(Number(b.dataset.extraChoice),b))}
const lifeRooms=[['bedroom','🛏️ Bedroom'],['living','🛋️ Living room'],['kitchen','🍳 Kitchen'],['garden','🌷 Garden']];
const collectables=['🧸','🎀','📚','🦄','💎','🪴','🎂','🐚','🧁','🪞','👑','👜','🎁','🕯️','🍓','🫖','🐠','🎈'];
function showLivingHouse(){game='livinghouse';const r=living.room||'bedroom',shelf=living.shelves[r]||[null,null,null],drawers=living.drawers[r]||[[],[],[]],chosen=living.selected||'',prizes=living.prizes||[];app.innerHTML=`<section class="panel"><div class="gamehead"><button class="secondary" id="lifeBack">← Games</button><strong>🏠 My Living Dollhouse</strong><span class="pill">🪙 ${coins}</span></div><p>Tap furniture to open it. Select a collectible below, then tap a shelf or open drawer to put it away!</p><div class="life-rooms">${lifeRooms.map(([id,name])=>`<button class="${r===id?'active':''}" data-life-room="${id}">${name}</button>`).join('')}</div><div class="life-room"><h2>${lifeRooms.find(x=>x[0]===r)[1]} ${living.party?'🎈🎉':''}</h2><div class="life-furniture"><button id="lifeLamp" title="Switch the light on or off">${living.lights[r]?'💡':'🪔'}</button><button id="lifeFridge" title="Open the fridge">${r==='kitchen'?'🧊':'🪞'}</button><button id="lifeCloset" title="Open closet">${living.closets[r]?'👗':'🚪'}</button><button id="lifeBed" title="Make the bed">${r==='bedroom'?'🛏️':r==='garden'?'🪴':'🛋️'}</button></div><h3>My shelves — tap an empty space to place an item</h3><div class="life-shelf">${[0,1,2].map(i=>`<button data-life-shelf="${i}">${shelf[i]||'＋'}</button>`).join('')}</div><h3>My dresser — open a drawer</h3>${[0,1,2].map(i=>`<button class="life-drawer ${living.openDrawer===i?'open':''}" data-life-drawer="${i}">🗄️ Drawer ${i+1} ${living.openDrawer===i?'▴':'▾'} ${living.openDrawer===i?`<div>${drawers[i].map((v,k)=>`<span data-drawer-object="${i}-${k}" style="font-size:30px;padding:5px">${v}</span>`).join('')||'Empty — choose something below and tap this drawer again'}</div>`:''}</button>`).join('')}</div><div class="life-actions"><button id="lifeParty">🎂 ${living.party?'End party':'Throw a birthday party'}</button><button id="lifeFish">🐠 Aquarium (${(living.fish||[]).length} fish)</button><button id="lifeShop">🛍️ Furniture shop</button></div><h3>🎁 Your little collectibles ${chosen?'— selected: '+chosen:''}</h3><div class="life-items">${[...collectables,...prizes].map((item,i)=>`<button data-life-item="${i}" class="${chosen===item?'active':''}">${item}</button>`).join('')}</div><p class="subtle">Tap a stored item to take it out. Your arrangements are saved on this device.</p><p id="lifeFeedback" class="feedback good"></p></section>`;$('#lifeBack').onclick=menu;document.querySelectorAll('[data-life-room]').forEach(b=>b.onclick=()=>{living.room=b.dataset.lifeRoom;living.openDrawer=-1;saveLiving();showLivingHouse()});document.querySelectorAll('[data-life-item]').forEach(b=>b.onclick=()=>{living.selected=[...collectables,...prizes][Number(b.dataset.lifeItem)];audio('tap');showLivingHouse()});document.querySelectorAll('[data-life-shelf]').forEach(b=>b.onclick=()=>{let arr=living.shelves[r]||[null,null,null],i=Number(b.dataset.lifeShelf);if(living.selected){arr[i]=living.selected;living.selected=''}else{living.selected=arr[i]||'';arr[i]=null}living.shelves[r]=arr;saveLiving();audio('good');showLivingHouse()});document.querySelectorAll('[data-life-drawer]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.lifeDrawer),arr=living.drawers[r]||[[],[],[]];if(living.openDrawer===i&&living.selected){arr[i].push(living.selected);living.selected='';living.drawers[r]=arr}else living.openDrawer=living.openDrawer===i?-1:i;saveLiving();audio('tap');showLivingHouse()});document.querySelectorAll('[data-drawer-object]').forEach(b=>b.onclick=e=>{e.stopPropagation();const [i,j]=b.dataset.drawerObject.split('-').map(Number);living.selected=living.drawers[r][i].splice(j,1)[0];saveLiving();showLivingHouse()});$('#lifeLamp').onclick=()=>{living.lights[r]=!living.lights[r];saveLiving();audio('tap');showLivingHouse()};$('#lifeCloset').onclick=()=>{living.closets[r]=!living.closets[r];saveLiving();showLivingHouse()};$('#lifeFridge').onclick=()=>{$('#lifeFeedback').textContent=r==='kitchen'?'🥛 The refrigerator is open! Choose a treat from your collectibles.':'✨ Mirror, mirror! Your room looks lovely!';audio('tap')};$('#lifeBed').onclick=()=>{$('#lifeFeedback').textContent='✨ You tidied up the room!';audio('good')};$('#lifeParty').onclick=()=>{living.party=!living.party;saveLiving();celebrate();showLivingHouse()};$('#lifeFish').onclick=()=>{$('#lifeFeedback').textContent='🐠 '+((living.fish||[]).join(' ')||'Rescue fish in Aquarium Rescue to fill your tank!')};$('#lifeShop').onclick=houseHome}
// Connect the living-house button to the original decorating page as well.
const oldHouseRender=houseRender;
houseRender=function(){oldHouseRender();const nav=document.querySelector('.house-nav');if(nav){nav.insertAdjacentHTML('beforeend','<button class="secondary" id="playHouse">🧸 Play inside</button>');$('#playHouse').onclick=showLivingHouse}};

/* Dedicated SEL arcade: scenario practice, not diagnostic or compliance training. */
const SEL_MODES=[
{id:'flex',emoji:'🦋',name:'Plan B Power',subtitle:'Flexible thinking when plans change',theme:'flexibility'},
{id:'pause',emoji:'🧊',name:'Pause & Choose',subtitle:'Practice stopping before reacting',theme:'impulse control'},
{id:'friend',emoji:'💬',name:'Friendship Studio',subtitle:'Friendship, boundaries, and repair',theme:'social skills'},
{id:'feel',emoji:'🌦️',name:'Feelings Detective',subtitle:'Notice emotions and body clues',theme:'emotional awareness'},
{id:'solve',emoji:'🧩',name:'Problem-Solving Lab',subtitle:'Find solutions that work for everyone',theme:'problem solving'},
{id:'reset',emoji:'🌈',name:'Calm-Down Lab',subtitle:'Try a tool and choose what helps you',theme:'self-regulation'}
];
const SEL_SCENES={
flex:[
['🎨🖌️','You planned to use the purple marker, but someone is using it.','What could you try?', ['Grab it from them.','Ask when they will be finished, or choose another color for now.','Give up on your whole picture.'],1,'It is disappointing when your first plan changes. You can keep your goal and try a different path.','“I wanted purple. Can I use it when you are done?”'],
['🍕🥪','You expected pizza for lunch, but today there are sandwiches.','Which response gives you the most choices?', ['Say what you hoped for and see what food options are available.','Throw the lunch away.','Refuse to talk to anyone.'],0,'You can be disappointed and still look for a workable option.','“I was expecting pizza. What else can I choose?”'],
['🎲🌧️','Your outdoor game is canceled because it is raining.','What is a flexible Plan B?', ['Tell everyone the day is ruined.','Keep asking until the weather changes.','Pick an indoor game and save the outdoor game for later.'],2,'Plan B does not mean you have to like the change. It means you can still have fun.','“I am disappointed. Can we do it tomorrow?”'],
['👟🚌','You wanted to be first in line, but another child got there first.','What helps?', ['Push ahead.','Choose where to stand and focus on getting to the activity.','Leave the line forever.'],1,'Not being first can feel frustrating. Your place in line does not decide your worth.','“I wanted first, but I can handle second.”']
],
pause:[
['🎮😤','You lose a game after trying really hard. Your hands feel tight.','What is a good first move?', ['Throw the controller.','Take one step back, unclench your hands, and decide what to say.','Call the other player names.'],1,'A pause gives your brain a moment to catch up with your feelings.','“I am frustrated. I need a minute.”'],
['📝💥','Your homework feels too hard and you want to rip the paper.','What could you do?', ['Ask for one hint or a short break.','Rip it immediately.','Pretend you finished.'],0,'Asking for support is a problem-solving skill, not a failure.','“Can you help me start just one question?”'],
['🗣️⚡','Someone interrupts while you are talking. You want to shout.','What is one way to respond?', ['Interrupt even louder.','Walk away without saying anything every time.','Say “I wasn’t finished yet” in a firm voice.'],2,'You can stand up for yourself without yelling or hurting someone.','“Please let me finish my thought.”'],
['🎒😠','Someone bumps your backpack. You do not know if it was on purpose.','What should you do first?', ['Ask what happened before deciding their intention.','Assume they did it to be mean.','Bump them back.'],0,'Checking the facts helps avoid a fight based on a guess.','“Hey, was that an accident?”']
],
friend:[
['👧👧🎲','A friend wants to play something different from you.','How can you both have a say?', ['Make them play your choice.','Offer to take turns choosing or find a game you both like.','Tell them you are not friends anymore.'],1,'Friends can want different things and still be friends.','“Can we do your game first and mine next?”'],
['🧸🙅','A friend says “No, I do not want a hug.”','What respects their boundary?', ['Hug them anyway.','Tell them they are mean.','Say “Okay” and give them space.'],2,'Everyone gets to decide about touch, including you.','“Okay! Would you like a wave instead?”'],
['💬😞','You said something that hurt a friend’s feelings.','What could help repair things?', ['Listen, apologize for the hurt, and ask what would help.','Tell them they are too sensitive.','Pretend nothing happened.'],0,'Repair means taking responsibility without deciding how fast someone must forgive.','“I am sorry I said that. I will try differently.”'],
['🧩👀','Two friends are talking quietly. You think they might be talking about you.','What is a fair way to handle the uncertainty?', ['Spread a rumor first.','Remember there are many possible explanations and ask kindly if needed.','Demand they stop talking.'],1,'A thought is not always a fact. You can check without accusing.','“I am feeling left out. Can I join you?”']
],
feel:[
['❤️‍🔥😡','Your cheeks get hot, your jaw tightens, and you want to shout.','Which feeling might be showing up?', ['Anger or frustration.','Sleepiness only.','Nothing at all.'],0,'Your body can give early clues. Noticing them helps you choose what to do next.','“My jaw is tight. I might need a break.”'],
['🦋😬','Your stomach feels fluttery before you try something new.','What could that mean?', ['You are definitely in danger.','You may be nervous or excited, or both.','You must quit.'],1,'Sometimes nervous and excited feel similar in the body.','“I have butterflies. I can try one small step.”'],
['🏆🥹','Your friend wins an award. You feel happy for them and a little jealous.','Is it okay to have two feelings?', ['No, pick one feeling.','Jealousy means you are a bad friend.','Yes. Mixed feelings are normal.'],2,'Feelings are information, not rules for how you must act.','“I am happy for her, and I wish I won too.”'],
['🌧️😔','A friend cancels plans. You feel sad and disappointed.','What is a useful next step?', ['Name your feeling and think of something else you would enjoy.','Tell them they can never be your friend.','Hide every feeling forever.'],0,'You can care about your plans and find another way to spend your time.','“I am disappointed. Maybe we can reschedule.”']
],
solve:[
['📚👯','Two people both want the same library book.','What could be a fair solution?', ['Take it secretly.','Ask about turns, a waitlist, or another copy.','Tell the other person they are selfish.'],1,'A good solution considers both people’s needs.','“Could I have it when you finish?”'],
['🏀🚫','A group says the team is full when you ask to join.','What can you do?', ['Ask when you can join next, or start another activity.','Insult the team.','Take the ball.'],0,'Being left out hurts. You can ask for inclusion and still choose another option.','“Can I play in the next round?”'],
['🧱👭','You and your partner disagree about how to build a project.','What could you suggest?', ['Refuse every idea except yours.','Stop the project.','Try both ideas in a small test and compare them.'],2,'Testing ideas turns an argument into teamwork.','“Let’s try your idea and mine.”'],
['🎂⏰','You have two things you want to do but only time for one.','How could you decide?', ['Get angry at the clock.','Choose what matters most now and plan the other for later.','Do neither.'],1,'Choosing one thing does not mean the other is gone forever.','“Which one matters most today?”']
]};
const SEL_GRADE4_MORE={"flex":[["📚🔄","Your teacher changes the assignment after you already started.","What is a useful next move?",["Complain until the old assignment comes back.","Ask what work you can keep and what needs changing.","Throw away your work."],1,"A changed direction is annoying. Clarifying the new expectations protects your effort.","“I started the first version. Which parts can I still use?”"],["👯📋","Your group votes for a project idea different from yours.","How can you stay involved?",["Refuse to contribute.","Tell everyone their idea is terrible.","Share one concern and help make the chosen idea work."],2,"Flexibility does not require pretending you agree. You can disagree respectfully and participate.","“I preferred mine, but how can I help with this plan?”"],["🏀📅","A friend promised to hang out but got invited to a team practice.","What response keeps options open?",["Say you are disappointed and ask to pick another day.","Tell everyone your friend is fake.","Demand they skip practice."],0,"Plans changing can sting. One change does not tell the whole story of a friendship.","“I was looking forward to it. Is Saturday possible?”"],["🧠✏️","You solved a math problem one way, but the teacher asks you to show a different method.","What helps you learn without giving up your approach?",["Insist your way is the only way.","Ask to compare the methods and understand why.","Refuse to show any work."],1,"Two methods can be useful even when you prefer one.","“Can you show me how your method connects to mine?”"],["🎤🔁","You prepared to present first, but the schedule changes and you go last.","What is a flexible strategy?",["Interrupt every presentation.","Leave class.","Use the extra time to rehearse and ask when your turn is."],2,"You can be frustrated while using the new situation to your advantage.","“I thought I was first. I'll practice once more.”"],["🧩🤝","Your partner wants to divide the work differently than you planned.","What is a fair way to adjust?",["Explain what you need and negotiate who does each part.","Do everything yourself without discussing it.","Stop working with them immediately."],0,"A plan can change through negotiation, not just giving in.","“I can do the research if you make the slides.”"]],"pause":[["📱💬","A classmate posts an embarrassing joke about you in the class chat.","What should you do before replying?",["Post something mean about them.","Save the message, pause, and decide whether to ask for removal or adult help.","Send ten angry messages."],1,"Online replies can spread quickly. You can protect yourself without escalating.","“Please take that down. It's not okay with me.”"],["🏫🗣️","The teacher corrects you in front of the class and you feel embarrassed.","Which response protects your point without starting an argument?",["Shout that the teacher is unfair.","Leave without permission.","Take a moment and ask to discuss it privately."],2,"Feeling embarrassed is understandable. A private conversation may get you heard.","“Could I explain what happened after class?”"],["📖😠","You studied hard but your quiz grade is lower than you expected.","What is a helpful first step?",["Check which questions you missed and ask for feedback.","Crumple the quiz and refuse to look.","Tell everyone the teacher hates you."],0,"A grade is information about this quiz, not a judgment of your intelligence.","“Can we go over the ones I missed?”"],["👭💢","A friend says something rude when other classmates are listening.","How can you respond without making it a bigger scene?",["Insult them back.","Say you didn't like it and talk later if needed.","Spread a rumor."],1,"Being firm is different from being hurtful.","“That wasn't funny to me. Let's talk later.”"],["⚽🤔","Someone says you cheated during a game, but you think you followed the rules.","What should you do first?",["Push them.","Quit the friendship forever.","Ask which rule they mean and explain your side calmly."],2,"A disagreement about rules can be solved by checking what happened.","“Which rule do you think I broke?”"],["✏️💭","You keep getting stuck on one homework question and want to stop everything.","What could help you restart?",["Mark the question, try another one, then ask for help.","Tear up the assignment.","Copy a friend's answers."],0,"Getting unstuck can mean changing the order, not giving up.","“I'll skip this one and come back.”"]],"friend":[["👭🚪","Two friends make weekend plans in front of you without inviting you.","What is a reasonable response?",["Tell them they are terrible people.","Notice how you feel, and ask about plans or make your own.","Demand they invite you."],1,"Feeling left out is real, but you cannot know their intentions without checking.","“That sounded fun. Are you planning a group thing?”"],["💬🔒","A friend tells you a secret that involves someone being unsafe.","What should you do?",["Promise never to tell anyone.","Share it with the whole class.","Tell a trusted adult who can help."],2,"Keeping a friendship secret is less important than someone's safety.","“I care about you, so I need help from an adult.”"],["📱😬","A friend keeps texting you when you want quiet time.","How can you set a boundary?",["Say when you can talk and put your phone away.","Block them without explanation every time.","Keep replying while getting angrier."],0,"A good boundary is clear and respectful.","“I'm offline tonight. I'll reply tomorrow.”"],["🤝🎒","Your friend wants you to say you saw something you didn't see so they avoid trouble.","What is the strongest friendship choice?",["Lie to prove loyalty.","Explain you care but won't make up a story.","Tell the whole class immediately."],1,"Real friendship does not require dishonesty.","“I can support you, but I can't say something that isn't true.”"],["👧🧑","A classmate you don't usually talk to asks to join your group.","What could you do?",["Ignore them.","Tell them nobody wants them.","Make space when possible or explain kindly if the group is assigned."],2,"Inclusion can be thoughtful without pretending every group has unlimited spots.","“We have room for one more. Want to help with the poster?”"],["🧑‍🤝‍🧑🗨️","You hear a rumor about your best friend.","What is the most responsible response?",["Don't repeat it; check with your friend privately if needed.","Forward it to see who believes it.","Treat the rumor as proof."],0,"Rumors are not evidence and repeating them can cause harm.","“I heard something confusing. Can I ask you directly?”"]],"feel":[["😬📢","You know the answer but freeze when the teacher calls on you.","What might be happening?",["You suddenly forgot everything forever.","You may feel nervous about speaking in front of people.","You must never participate again."],1,"Performance nerves can make thinking harder even when you know the material.","“Could I have a second to think?”"],["😤📚","You get irritated at small noises after a long school day.","What could this tell you?",["Everyone is trying to annoy you.","You are a bad person.","You may be mentally tired or overloaded."],2,"Irritability can be a clue that you need rest, food, quiet, or a break.","“I'm overloaded. I need ten quiet minutes.”"],["🏆😕","You get a good grade but feel disappointed because your friend did better.","Which statement makes sense?",["You can feel proud and disappointed at the same time.","You are not allowed to feel disappointed.","Your friend's success takes away yours."],0,"Mixed feelings are normal, and comparisons can hide your own progress.","“I improved, even though I hoped for more.”"],["👭💔","A close friend sits with someone else at lunch and your stomach drops.","What might your reaction mean?",["They definitely dislike you.","You may be feeling insecure or worried about being left out.","You should end the friendship."],1,"A strong feeling is real, but it is not always proof of what another person thinks.","“I felt left out today. Can we catch up?”"],["🎤🌟","You're excited to perform but also scared you'll make a mistake.","What is true?",["You should cancel.","Being nervous means you aren't ready.","Excitement and fear can happen together."],2,"Courage can mean doing something meaningful while feeling nervous.","“I'm nervous because this matters to me.”"],["😶‍🌫️🧠","You snap at someone, then realize you barely slept.","What is a useful insight?",["Sleep and stress can affect how strongly you react.","You never need to apologize if you're tired.","The other person caused all your feelings."],0,"Understanding a trigger helps you plan, while still taking responsibility for your actions.","“I'm sorry I snapped. I'm tired and need a break.”"]],"solve":[["👩‍🏫👭","Your group project partner hasn't done their part and it's due tomorrow.","What should you do?",["Do nothing and hope.","Ask what is done, agree on a specific plan, and involve the teacher if needed.","Tell everyone they are lazy."],1,"Clear expectations and early communication help more than guessing.","“Can you finish the slides tonight? If not, let's tell the teacher.”"],["📱🚫","Someone shares your photo without asking.","What is a reasonable next step?",["Share an embarrassing photo of them.","Pretend it doesn't bother you.","Ask them to remove it and get adult help if they refuse."],2,"You can set boundaries about your image and privacy.","“Please delete that photo. I didn't agree to share it.”"],["🏀⚖️","Two classmates argue about whether a ball was out of bounds.","How could you help?",["Suggest replaying the point or asking a neutral person.","Pick your friend's side automatically.","Yell louder than both."],0,"A neutral rule helps when memories differ.","“Let's replay the point so it's fair.”"],["📝👯","Your partner changes your writing without asking and you dislike it.","What is a useful response?",["Delete all their work.","Explain which changes bother you and agree how to edit together.","Refuse to speak to them."],1,"Collaboration works better when everyone knows the editing rules.","“Can we check with each other before changing paragraphs?”"],["🍽️🪑","You want to sit with your usual group, but their table is full.","What is a practical solution?",["Push into the table.","Accuse them of excluding you.","Ask if anyone can move or sit elsewhere today and reconnect later."],2,"A full table is frustrating, but it does not automatically mean rejection.","“Is there room if we move over? If not, see you at recess.”"],["🧠🗓️","You have a test, homework, and a project all due soon.","What is the best planning move?",["List deadlines, break tasks into steps, and ask for help prioritizing.","Try everything at once until you're exhausted.","Ignore the dates."],0,"Breaking work down makes a busy week more manageable.","“I'll do the first ten minutes of the project now.”"]]};
