const RIKI_SCENE=[
 ['You are playing tag at the park, but your friend is standing alone.',['🌳','Everyone is running on the grass.'],['👟','Your friend is still by the bench.'],['😕','They look unsure about joining.'],'They may want an invitation or may need a break.','Would you like to play tag with us?'],
 ['Someone bumps your lunch tray and your food spills.',['🍱','The lunch is on the floor.'],['😢','You look upset and disappointed.'],['😧','The other child looks surprised.'],'It may have been an accident, even though losing lunch feels upsetting.','My lunch spilled. Can you help me clean up?'],
 ['Your friend walks away while you are talking.',['⏰','She keeps checking the clock.'],['🎒','She picks up her backpack.'],['😟','She looks worried.'],'Maybe she has to get somewhere.','Could we finish talking later?'],
 ['Two classmates whisper nearby.',['🎁','They are hiding a gift bag.'],['👀','You cannot hear their words.'],['😊','One of them is smiling.'],'You do not know what they are saying.','What are you two planning?'],
 ['A teammate is quiet after a project.',['📄','Her drawing was not included.'],['🗳️','Others voted without asking.'],['😔','She looks disappointed.'],'She might feel left out.','Would you like to show us your idea?'],
 ['A friend does not reply to a message.',['📱','The message is unread.'],['🏀','She has practice today.'],['🕒','Only a little time has passed.'],'She may be busy.','Talk when you have time!']
];
let rikiScene=null;
function rikiSceneStart(){game='sel';session=null;rikiScene={at:0,opened:[],done:false,paid:false};rikiSceneDraw()}
const RIKI_STORY_OPTIONS=[
 [['invite','Invite your friend to join','They come over and join the game!'],['ask','Ask whether they want to play','Your friend explains what they need.'],['ignore','Keep playing without them','Your friend stays alone and looks disappointed.']],
 [['help','Help clean up the spilled food','You kneel down, gather the food, and your friend helps.'],['ask','Ask if it was an accident','You hear their explanation and they offer to help.'],['blame','Yell at the other child','The child steps away, looking upset. The food is still on the floor.']],
 [['ask','Ask why your friend is leaving','They explain they have to catch their ride.'],['help','Suggest talking later','Your friend nods and agrees.'],['blame','Accuse them of ignoring you','Your friend looks hurt and leaves.']],
 [['ask','Ask what they are talking about','They explain they are planning a surprise.'],['help','Give them some privacy','You keep playing while they finish their surprise.'],['blame','Accuse them of gossiping','They look confused and uncomfortable.']],
 [['ask','Ask your teammate what happened','They explain that their idea was not heard.'],['help','Invite them to share their drawing','Your teammate shows the group their design.'],['blame','Tell them to stop being quiet','Your teammate turns away, still feeling excluded.']],
 [['ask','Wait and check in later','Your friend replies after practice.'],['help','Send a friendly no-pressure message','Your friend sees a kind message when free.'],['blame','Send an angry message','Your friend feels pressured and upset.']]
];
function rikiStoryVisual(index,choice,phase){
 const theme=['park','lunch','hall','whisper','team','phone'][index],hurt=choice==='blame'||choice==='ignore',help=choice==='help'||choice==='invite',resolved=phase==='result';
 const sceneBack={park:'#b4e9cc',lunch:'#ffe9ce',hall:'#e3d9fc',whisper:'#ffdfed',team:'#d4eaff',phone:'#d8e9ff'}[theme];
 let props='';
 if(theme==='lunch')props='<g class="riki-story-tray"><rect x="137" y="164" width="95" height="17" rx="8" fill="#aa8db7"/><circle cx="166" cy="162" r="13" fill="#f4b55e"/><circle cx="194" cy="160" r="11" fill="#91bd68"/></g><g class="riki-story-food"><circle cx="145" cy="228" r="10" fill="#f4b55e"/><circle cx="175" cy="235" r="8" fill="#8dbd68"/><circle cx="207" cy="226" r="9" fill="#ef8c7a"/></g>';
 else if(theme==='park')props='<circle class="riki-story-ball" cx="188" cy="224" r="15" fill="#ffdc71" stroke="#fff" stroke-width="5"/><path d="M20 190V100" stroke="#926f51" stroke-width="14"/><circle cx="20" cy="86" r="43" fill="#75c78e"/>';
 else if(theme==='phone')props='<g class="riki-story-object"><rect x="148" y="169" width="66" height="70" rx="9" fill="#4e6395"/><rect x="155" y="178" width="52" height="48" rx="5" fill="#e2f6ff"/><path d="M164 194H199M164 207H192" stroke="#7ca3c2" stroke-width="5"/></g>';
 else if(theme==='team')props='<g class="riki-story-object"><rect x="145" y="180" width="92" height="60" rx="6" fill="#fff"/><path d="M158 220L178 190 201 211 221 190" stroke="#e58fb1" stroke-width="7" fill="none"/></g>';
 else if(theme==='whisper')props='<g class="riki-story-object"><rect x="159" y="179" width="62" height="56" rx="8" fill="#e5a7ce"/><path d="M159 190L190 209 221 190" fill="none" stroke="#fff" stroke-width="6"/></g>';
 else props='<g class="riki-story-object"><rect x="163" y="176" width="55" height="63" rx="8" fill="#f4bc84"/><path d="M175 193H207M175 208H207" stroke="#fff" stroke-width="5"/></g>';
 const person=(x,shirt,second)=>'<g class="riki-story-actor '+(second?'riki-story-second':'riki-story-first')+'" transform="translate('+x+' 0)"><ellipse cx="0" cy="237" rx="30" ry="7" fill="#654a6e" opacity=".18"/><path d="M-13 188L-19 234M13 188L19 234" stroke="#796b93" stroke-width="12" stroke-linecap="round"/><path d="M-29 141Q0 123 29 141L28 197Q0 208-28 197Z" fill="'+shirt+'" stroke="#fff" stroke-width="4"/><path class="riki-story-arm" d="M-26 150L-38 185M26 150L38 185" stroke="#e4b89e" stroke-width="11" stroke-linecap="round"/><circle cx="0" cy="104" r="38" fill="#f2c8a8" stroke="#fff9" stroke-width="4"/><path d="M-38 102Q-40 52 0 57Q42 53 38 102L25 79Q0 67-24 82Z" fill="'+(second?'#9a6c4e':'#704c53')+'"/><ellipse cx="-13" cy="105" rx="4" ry="5" fill="#47384d"/><ellipse cx="13" cy="105" rx="4" ry="5" fill="#47384d"/><path d="'+(hurt?'M-13 132Q0 118 13 132':resolved?'M-13 124Q0 140 13 124':'M-8 127Q0 131 8 127')+'" fill="none" stroke="#a85c69" stroke-width="4" stroke-linecap="round"/></g>';
 return '<div class="riki-story-theater riki-story-'+theme+' '+(resolved?'riki-story-result ':'')+(hurt?'riki-story-unkind':help?'riki-story-helpful':'riki-story-curious')+'" role="img" aria-label="Animated story showing the characters and the consequence of your choice"><svg viewBox="0 0 360 260" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="rikiStorySky" x2="0" y2="1"><stop stop-color="'+sceneBack+'"/><stop offset="1" stop-color="#fff9f0"/></linearGradient></defs><rect width="360" height="260" rx="22" fill="url(#rikiStorySky)"/><rect x="0" y="239" width="360" height="21" fill="#a5c7b4"/><circle cx="313" cy="42" r="24" fill="#fff5b8"/>'+person(92,'#e8a3d2',false)+person(270,'#a6b6f0',true)+props+'</svg><p class="riki-story-caption">'+(phase==='intro'?'Watch what happens…':phase==='choose'?'What should Riki do?':' ')+'</p></div>';
}
function rikiSceneDraw(){
 const a=rikiScene,q=RIKI_SCENE[a.at];
 if(!q){if(!a.paid){a.paid=true;award(18)}app.innerHTML='<section class="panel riki-clay-stage"><h2>🏆 Stories complete!</h2><p>You practiced six real-life situations. You earned 18 coins!</p><button class="primary" id="rikiSceneAgain">Play again</button><button class="secondary" id="rikiSceneBack">Social Skills</button></section>';$('#rikiSceneAgain').onclick=rikiSceneStart;$('#rikiSceneBack').onclick=selHub;return}
 const phase=a.phase||'intro',opts=RIKI_STORY_OPTIONS[a.at],chosen=opts.find(o=>o[0]===a.choice);
 let html='<section class="panel riki-clay-stage riki-story-game"><button class="secondary" id="rikiSceneBack">← Social Skills</button><p>Story '+(a.at+1)+' of '+RIKI_SCENE.length+'</p><h2>🎬 Social Detective</h2><p>'+selSafe(q[0])+'</p>'+rikiStoryVisual(a.at,a.choice,phase);
 if(phase==='intro')html+='<button class="primary" id="rikiStoryBegin">▶ See what happens</button>';
 else{html+='<h3>Choose what happens next</h3><div class="riki-story-options">'+opts.map(o=>'<button type="button" class="sel-choice" data-riki-story-option="'+o[0]+'" aria-pressed="'+(a.choice===o[0])+'">'+selSafe(o[1])+'</button>').join('')+'</div>';if(chosen)html+='<div class="sel-feedback" role="status"><h3>'+selSafe(chosen[2])+'</h3><p>'+selSafe(q[4])+'</p>'+(a.choice==='blame'||a.choice==='ignore'?'<p>Try another response to help the situation.</p>':'<p><strong>You could say:</strong> '+selSafe(q[5])+'</p><button class="primary" id="rikiSceneNext">Next story →</button>')+'<button class="secondary" id="rikiStoryReplay">↻ Watch again</button></div>';}
 html+='</section>';app.innerHTML=html;$('#rikiSceneBack').onclick=selHub;
 const begin=$('#rikiStoryBegin');if(begin)begin.onclick=()=>{a.phase='choose';a.choice=null;rikiSceneDraw()};
 document.querySelectorAll('[data-riki-story-option]').forEach(btn=>btn.onclick=()=>{a.choice=btn.dataset.rikiStoryOption;a.phase='result';rikiSceneDraw()});
 const replay=$('#rikiStoryReplay');if(replay)replay.onclick=()=>{a.phase='choose';a.choice=null;rikiSceneDraw()};
 const next=$('#rikiSceneNext');if(next)next.onclick=()=>{a.at++;a.choice=null;a.phase='intro';rikiSceneDraw()};
}
(function(){const st=document.createElement('style');st.id='rikiStoryGameStyle';st.textContent='.riki-story-game{text-align:center}.riki-story-theater{max-width:540px;margin:15px auto;overflow:hidden;border-radius:23px;background:#f5eaff;border:4px solid #fff;box-shadow:0 8px 25px #6e519333}.riki-story-theater svg{display:block;width:100%;height:auto}.riki-story-caption{margin:0;padding:12px;background:#fff8db;color:#674b74;font-weight:800}.riki-story-options{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin:12px 0}.riki-story-options button{min-height:66px;white-space:normal}.riki-story-theater .riki-story-actor,.riki-story-theater .riki-story-food,.riki-story-theater .riki-story-tray,.riki-story-theater .riki-story-object{transform-box:fill-box;transform-origin:center}.riki-story-lunch .riki-story-food{animation:rikiFoodDrop 1.2s ease-out both}.riki-story-lunch .riki-story-tray{animation:rikiTrayTip 1.2s ease-in-out both}.riki-story-result.riki-story-helpful .riki-story-first{animation:rikiStoryBend 1.2s ease-in-out both}.riki-story-result.riki-story-helpful .riki-story-food{animation:rikiFoodClean 1.2s ease-in-out both}.riki-story-result.riki-story-unkind .riki-story-second{animation:rikiStoryWithdraw 1.2s ease-in-out both}.riki-story-result.riki-story-curious .riki-story-second{animation:rikiStoryTalk 1.2s ease-in-out both}.riki-story-result.riki-story-helpful .riki-story-second{animation:rikiStoryJoin 1.2s ease-in-out both}.riki-story-result.riki-story-park .riki-story-ball{animation:rikiStoryBounce 1.2s ease-in-out both}@keyframes rikiFoodDrop{from{opacity:0;transform:translateY(-55px)}to{opacity:1;transform:translateY(0)}}@keyframes rikiTrayTip{50%{transform:rotate(22deg)}to{transform:rotate(0)}}@keyframes rikiStoryBend{50%{transform:translate(38px,16px) rotate(12deg)}to{transform:translate(40px,0)}}@keyframes rikiFoodClean{to{opacity:0;transform:translateY(-45px)}}@keyframes rikiStoryWithdraw{to{transform:translateX(38px);opacity:.65}}@keyframes rikiStoryTalk{50%{transform:translateY(-8px)}to{transform:translateX(-12px)}}@keyframes rikiStoryJoin{to{transform:translateX(-85px)}}@keyframes rikiStoryBounce{50%{transform:translateY(-55px)}}@media(prefers-reduced-motion:reduce){.riki-story-theater *{animation:none!important}}';document.head.appendChild(st)})();
