 q[1].forEach((label,i)=>html+='<button class="riki-clay-object" draggable="true" data-riki-build="'+i+'">'+selSafe(label)+'</button>');html+='</div><div id="rikiBuildZone" tabindex="0" role="button" aria-label="Build area, tap after selecting a material or drag it here" style="margin:14px auto;padding:20px;border:4px dashed #ac85d5;border-radius:22px;min-height:105px;text-align:center;background:linear-gradient(#e4f7ff,#f7dfff)">🏗️ Drop your teamwork move here, or tap a choice above</div><p id="rikiBuildHint" role="status">Choose what to do next.</p></section>';app.innerHTML=html;$('#rikiTeamBack').onclick=selHub;
 function place(i){if(a.step===0||i===0){a.parts.push(['🏗️','🧱','💡','✨'][a.step]);a.step++;rikiTeamDraw()}else{$('#rikiBuildHint').textContent='Try a teamwork move that includes both builders. You can try again!'}}
