document.addEventListener('input',e=>{if(e.target.id==='rikiEmotionLevel'){const n=Number(e.target.value);const out=document.getElementById('rikiEmotionReadout');if(out)out.textContent=['','🙂 Small','😕 Growing','😟 Medium','😢 Big','😭 Very big'][n]+' feeling'}});
function selCalm(){app.innerHTML=`<section class="panel">${selHeader('🌈 Calm-Down Lab')}<div class="sel-scene"><div style="max-width:210px;margin:auto">${rikiClayArt("calm")}</div>${rikiEmotionMeter()}<div class="sel-breath">🫧</div><button type="button" class="primary" id="rikiBreathPlay">🌬️ Breathe with the bubble</button><p id="rikiBreathStatus" role="status">Press to practice a slow breath.</p><h2>You get to choose what helps you.</h2><p>Calming down is a skill, not a punishment. Different tools work for different people.</p></div><div class="sel-grid">${CALM_TOOLS.map((t,i)=>`<button class="sel-card" data-calm="${i}"><span class="sel-emoji">${t[0]}</span><strong>${t[1]}</strong><p>${t[2]}</p></button>`).join('')}</div>${selCalmTool?`<div class="sel-feedback"><h3>${selCalmTool}</h3><p>Try it at your own pace. Would this tool help in a real-life moment? You get to decide.</p><p>🪙 Earn 3 coins for trying a new tool (up to 3 tools each day).</p></div>`:''}</section>`;$('#selBack').onclick=selHub;const breath=$('#rikiBreathPlay');if(breath)breath.onclick=()=>{const bubble=document.querySelector('.sel-breath');const status=$('#rikiBreathStatus');if(bubble){bubble.animate?.([{transform:'scale(.7)',opacity:.6},{transform:'scale(1.6)',opacity:1,offset:.5},{transform:'scale(.7)',opacity:.6}],{duration:5000,iterations:1,easing:'ease-in-out'})}if(status)status.textContent='Breathe in slowly as the bubble grows, then out as it shrinks.'};document.querySelectorAll('[data-calm]').forEach(b=>b.onclick=()=>{selCalmTool=CALM_TOOLS[Number(b.dataset.calm)][1];const key='rikiCalmRewardDateV1',today=new Date().toLocaleDateString('en-CA');try{const record=JSON.parse(localStorage.getItem(key)||'{}');if(record.date!==today){record.date=today;record.used=[]}const index=Number(b.dataset.calm);if(!record.used.includes(index)&&record.used.length<3){record.used.push(index);localStorage.setItem(key,JSON.stringify(record));award(3)}}catch(_){}audio('tap');selCalm()})}
